export type TranslationKey = keyof (typeof copy)["en"];

export function isLang(value: string | null): value is Lang {
  return LANGUAGES.some((language) => language.code === value);
}

export function localeFor(language: Lang): string {
  return LANGUAGES.find((item) => item.code === language)?.locale || "en-GB";
}

export function translate(language: Lang, key: TranslationKey, vars: Record<string, string | number> = {}): string {
  let text: string = (copy[language] as any)[key] || (copy.en as any)[key];
  for (const [name, value] of Object.entries(vars)) text = text.replaceAll(`{${name}}`, String(value));
  return text;
}
